    blk=None
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]!=bg and g[r+1][c]!=bg and g[r][c+1]!=bg and g[r+1][c+1]!=bg and g[r][c]==g[r+1][c]==g[r][c+1]==g[r+1][c+1]:
                blk=(r,c,g[r][c]); break
        if blk:break
    br,bc,col=blk
    res=[row[:] for row in g]
    for r,c in [(rr,c) for rr in range(h)]+[] : pass
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and g[r][c]!=col:
                pts=[(r,c)]
                for mr,mc in [(2*br-r,2*bc-c),(2*br-r,c),(r,2*bc-c)]:
                    pts.append((mr,mc))
                for p in pts:
                    if 0<=p[0]<h and 0<=p[1]<w: res[p[0]][p[1]]=col
    return res
